const body = $input.first().json.body || {};
const entry = (body.entry && body.entry[0]) || {};
const messagingEvent = (entry.messaging && entry.messaging[0]) || {};

const senderId = messagingEvent.sender ? messagingEvent.sender.id : '';
let text = '';
let payload = '';
let isEcho = false;

if (messagingEvent.message) {
  text = messagingEvent.message.text || '';
  isEcho = !!messagingEvent.message.is_echo;
  if (messagingEvent.message.quick_reply) {
    payload = messagingEvent.message.quick_reply.payload || '';
  }
} else if (messagingEvent.postback) {
  text = messagingEvent.postback.title || '';
  payload = messagingEvent.postback.payload || '';
}

return [{
  json: {
    senderId,
    text: text.trim(),
    textLower: text.trim().toLowerCase(),
    payload,
    isEcho
  }
}];

// ==== BUSINESS CONFIG - edit these ====
const BUSINESS_START_HOUR = 9;
const BUSINESS_END_HOUR = 18;
const OPEN_DAYS = [1,2,3,4,5,6]; // 0=Sun ... 6=Sat, Mon-Sat here
const DAYS_AHEAD_TO_SHOW = 14;
// ========================================

const msg = $('Extract Message Data').item.json;
const sessionRows = $('Get Session').all();
const servicesRows = $('Get Services').all();

const services = servicesRows
  .filter(r => r.json && r.json.name)
  .map(r => ({
    name: r.json.name,
    payload: r.json.payload,
    durationMinutes: parseInt(r.json.durationMinutes, 10) || 30
  }));

const foundRow = sessionRows.find(r => r.json && r.json.senderId === msg.senderId);
let session = foundRow ? { ...foundRow.json } : {
  senderId: msg.senderId, step: 'NEW', name: '', address: '', phone: '',
  email: '', service: '', serviceDuration: '', date: '', time: ''
};

const RESTART_WORDS = ['menu', 'restart', 'start over', 'cancel'];
if (session.step === 'DONE' || RESTART_WORDS.includes(msg.textLower)) {
  session.step = 'NEW';
}

// Facebook quick reply titles must be 20 chars or fewer, or the whole message is rejected
function quickReplies(options) {
  return options.map(o => ({ content_type: 'text', title: (o.title || '').slice(0, 20), payload: o.payload }));
}
function reply(text, qr) {
  return { text, quick_replies: qr && qr.length ? qr : undefined };
}
const MAIN_MENU_QR = quickReplies([
  { title: 'Book Appointment', payload: 'BOOK_APPT' },
  { title: 'Live Agent', payload: 'LIVE_AGENT' }
]);

let action = 'REPLY';
let out = { session, reply: null, senderId: msg.senderId };

switch (session.step) {
  case 'NEW': {
    session.step = 'AWAIT_CHOICE';
    out.reply = reply("Hi! \ud83d\udc4b Would you like to book an appointment or chat with a live person?", MAIN_MENU_QR);
    break;
  }
  case 'AWAIT_CHOICE': {
    if (msg.payload === 'LIVE_AGENT') {
      session.step = 'LIVE_AGENT';
      out.reply = reply("Sure! A team member will reply to you here shortly. \ud83d\ude42");
    } else {
      session.step = 'AWAIT_NAME';
      out.reply = reply("Great, let's get you booked. What's your full name?");
    }
    break;
  }
  case 'AWAIT_NAME': {
    session.name = msg.text;
    session.step = 'AWAIT_ADDRESS';
    out.reply = reply(`Thanks, ${session.name}! What's your address?`);
    break;
  }
  case 'AWAIT_ADDRESS': {
    session.address = msg.text;
    session.step = 'AWAIT_PHONE';
    out.reply = reply("Got it. What's the best phone number to reach you?");
    break;
  }
  case 'AWAIT_PHONE': {
    session.phone = msg.text;
    session.step = 'AWAIT_EMAIL';
    out.reply = reply("Thanks! What's your email address?");
    break;
  }
  case 'AWAIT_EMAIL': {
    session.email = msg.text;
    session.step = 'AWAIT_SERVICE';
    out.reply = reply("What type of service would you like to book?",
      quickReplies(services.slice(0, 11).map(s => ({ title: s.name, payload: `SERVICE_${s.payload}` }))));
    break;
  }
  case 'AWAIT_SERVICE': {
    const code = (msg.payload || '').replace('SERVICE_', '');
    const chosen = services.find(s => s.payload === code) || services.find(s => s.name.toLowerCase() === msg.textLower);
    if (!chosen) {
      out.reply = reply("Sorry, please choose a service from the list below.",
        quickReplies(services.slice(0, 11).map(s => ({ title: s.name, payload: `SERVICE_${s.payload}` }))));
      break;
    }
    session.service = chosen.name;
    session.serviceDuration = chosen.durationMinutes;
    action = 'NEED_DATES';
    break;
  }
  case 'AWAIT_DATE': {
    const chosenDate = (msg.payload || '').replace('DATE_', '');
    if (!chosenDate) {
      out.reply = reply("Please pick one of the available dates above.");
      break;
    }
    session.date = chosenDate;
    action = 'NEED_TIMES';
    break;
  }
  case 'AWAIT_TIME': {
    const chosenTime = (msg.payload || '').replace('TIME_', '');
    if (!chosenTime) {
      out.reply = reply("Please pick one of the available times above.");
      break;
    }
    session.time = chosenTime;
    session.step = 'AWAIT_CONFIRM';
    out.reply = reply(
      `Please confirm:\n\nService: ${session.service}\nDate: ${session.date}\nTime: ${session.time}\nName: ${session.name}\nPhone: ${session.phone}\n\nShall I book this?`,
      quickReplies([{ title: 'Yes, book it', payload: 'CONFIRM_YES' }, { title: 'No, start over', payload: 'CONFIRM_NO' }])
    );
    break;
  }
  case 'AWAIT_CONFIRM': {
    if (msg.payload === 'CONFIRM_YES') {
      action = 'CREATE_BOOKING';
    } else {
      session.step = 'AWAIT_CHOICE';
      out.reply = reply("No problem, let's start over. Would you like to book an appointment or chat with a live person?", MAIN_MENU_QR);
    }
    break;
  }
  case 'LIVE_AGENT': {
    out.reply = null;
    break;
  }
  default: {
    session.step = 'AWAIT_CHOICE';
    out.reply = reply("Hi! Would you like to book an appointment or chat with a live person?", MAIN_MENU_QR);
  }
}

out.action = action;
return [{ json: out }];

const engine = $('Conversation Engine').first().json;
const session = engine.session;
const events = $input.all().map(i => i.json).filter(e => e && e.start && (e.start.dateTime || e.start.date));

const BUSINESS_START_HOUR = 9;
const BUSINESS_END_HOUR = 18;
const OPEN_DAYS = [1,2,3,4,5,6];
const DAYS_AHEAD = 14;
const BUSINESS_TZ_OFFSET = '+08:00'; // Asia/Manila - change if your business is elsewhere
const BUSINESS_TZ_NAME = 'Asia/Manila';
const durationMin = parseInt(session.serviceDuration, 10) || 30;

function pad(n) { return String(n).padStart(2, '0'); }
function manilaDateStr(epochMs) {
  return new Date(epochMs + 8 * 3600000).toISOString().slice(0, 10);
}

const busy = events.map(e => ({
  start: new Date(e.start.dateTime || e.start.date).getTime(),
  end: new Date(e.end.dateTime || e.end.date).getTime()
}));

const todayStr = manilaDateStr(Date.now());
const todayMidnightMs = new Date(`${todayStr}T00:00:00${BUSINESS_TZ_OFFSET}`).getTime();

function hasFreeSlot(dateStr) {
  const dayStartMs = new Date(`${dateStr}T${pad(BUSINESS_START_HOUR)}:00:00${BUSINESS_TZ_OFFSET}`).getTime();
  const dayEndMs = new Date(`${dateStr}T${pad(BUSINESS_END_HOUR)}:00:00${BUSINESS_TZ_OFFSET}`).getTime();
  let cursor = dayStartMs;
  while (cursor + durationMin * 60000 <= dayEndMs) {
    const slotEnd = cursor + durationMin * 60000;
    const overlap = busy.some(b => cursor < b.end && slotEnd > b.start);
    if (!overlap) return true;
    cursor += 30 * 60000;
  }
  return false;
}

const availableDates = [];
for (let i = 1; i <= DAYS_AHEAD && availableDates.length < 10; i++) {
  const dayMs = todayMidnightMs + i * 86400000;
  const dateStr = manilaDateStr(dayMs);
  const dow = new Date(`${dateStr}T12:00:00${BUSINESS_TZ_OFFSET}`).getUTCDay();
  if (!OPEN_DAYS.includes(dow)) continue;
  if (hasFreeSlot(dateStr)) availableDates.push(dateStr);
}

const quick_replies = availableDates.map(dateStr => {
  const label = new Date(`${dateStr}T12:00:00${BUSINESS_TZ_OFFSET}`)
    .toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', timeZone: BUSINESS_TZ_NAME });
  return { content_type: 'text', title: label.slice(0, 20), payload: `DATE_${dateStr}` };
});

session.step = 'AWAIT_DATE';

return [{
  json: {
    session,
    senderId: engine.senderId,
    reply: {
      text: availableDates.length
        ? `Great, you'd like ${session.service}. Here are the next available dates:`
        : "Sorry, there are no available dates in the next two weeks. Please contact us directly.",
      quick_replies: quick_replies.length ? quick_replies : undefined
    }
  }
}];

const engine = $('Conversation Engine').first().json;
const session = engine.session;
const events = $input.all().map(i => i.json).filter(e => e && e.start && (e.start.dateTime || e.start.date));

const BUSINESS_START_HOUR = 9;
const BUSINESS_END_HOUR = 18;
const BUSINESS_TZ_OFFSET = '+08:00'; // Asia/Manila - change if your business is elsewhere
const BUSINESS_TZ_NAME = 'Asia/Manila';
const durationMin = parseInt(session.serviceDuration, 10) || 30;

function pad(n) { return String(n).padStart(2, '0'); }

const busy = events.map(e => ({
  start: new Date(e.start.dateTime || e.start.date).getTime(),
  end: new Date(e.end.dateTime || e.end.date).getTime()
}));

const dateStr = session.date;
const dayStartMs = new Date(`${dateStr}T${pad(BUSINESS_START_HOUR)}:00:00${BUSINESS_TZ_OFFSET}`).getTime();
const dayEndMs = new Date(`${dateStr}T${pad(BUSINESS_END_HOUR)}:00:00${BUSINESS_TZ_OFFSET}`).getTime();

const slots = [];
let cursor = dayStartMs;
while (cursor + durationMin * 60000 <= dayEndMs) {
  const slotEnd = cursor + durationMin * 60000;
  const overlap = busy.some(b => cursor < b.end && slotEnd > b.start);
  if (!overlap) slots.push(cursor);
  cursor += 30 * 60000;
}

const quick_replies = slots.slice(0, 11).map(ms => {
  const label = new Date(ms).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', timeZone: BUSINESS_TZ_NAME });
  const manilaMs = ms + 8 * 3600000;
  const hh = pad(new Date(manilaMs).getUTCHours());
  const mm = pad(new Date(manilaMs).getUTCMinutes());
  return { content_type: 'text', title: label.slice(0, 20), payload: `TIME_${hh}:${mm}` };
});

session.step = slots.length ? 'AWAIT_TIME' : 'AWAIT_DATE';

return [{
  json: {
    session,
    senderId: engine.senderId,
    reply: {
      text: slots.length ? `Available times on ${session.date}:` : `Sorry, no open times on ${session.date}. Please pick another date.`,
      quick_replies: quick_replies.length ? quick_replies : undefined
    }
  }
}];

const engine = $('Conversation Engine').first().json;
const session = engine.session;
const durationMin = parseInt(session.serviceDuration, 10) || 30;
const BUSINESS_TZ_OFFSET = '+08:00'; // Asia/Manila - change if your business is elsewhere
const start = new Date(`${session.date}T${session.time}:00${BUSINESS_TZ_OFFSET}`);
const end = new Date(start.getTime() + durationMin * 60000);

return [{
  json: {
    session,
    senderId: engine.senderId,
    startISO: start.toISOString(),
    endISO: end.toISOString()
  }
}];

const engine = $('Conversation Engine').first().json;
const session = { ...engine.session, step: 'NEW', date: '', time: '', service: '', serviceDuration: '' };

return [{
  json: {
    session,
    senderId: engine.senderId,
    reply: {
      text: `You're all set! \u2705\n\n${engine.session.service} booked for ${engine.session.date} at ${engine.session.time}.\nWe'll see you then, ${engine.session.name}! Reply \"menu\" anytime to book again.`
    }
  }
}];
